// Builds { slug -> { srcSet, fallback } } maps from the optimized asset folders
// generated by scripts/optimize-images.mjs, so components never hand-wire file paths.
const workWebp = import.meta.glob('../assets/work/*.webp', { eager: true, query: '?url', import: 'default' })
const workJpg = import.meta.glob('../assets/work/*.jpg', { eager: true, query: '?url', import: 'default' })
const profileWebp = import.meta.glob('../assets/profile/*.webp', { eager: true, query: '?url', import: 'default' })
const profileJpg = import.meta.glob('../assets/profile/*.jpg', { eager: true, query: '?url', import: 'default' })

function buildSet(webpModules, jpgModules) {
  const bySlug = {}

  for (const [filePath, url] of Object.entries(webpModules)) {
    const name = filePath.split('/').pop().replace('.webp', '')
    const match = name.match(/^(.+)-(\d+)$/)
    if (!match) continue
    const [, slug, width] = match
    bySlug[slug] ??= { widths: [], fallback: '' }
    bySlug[slug].widths.push({ width: Number(width), url })
  }

  for (const [filePath, url] of Object.entries(jpgModules)) {
    const slug = filePath.split('/').pop().replace('.jpg', '')
    bySlug[slug] ??= { widths: [], fallback: '' }
    bySlug[slug].fallback = url
  }

  const result = {}
  for (const [slug, { widths, fallback }] of Object.entries(bySlug)) {
    widths.sort((a, b) => a.width - b.width)
    result[slug] = {
      srcSet: widths.map(({ url, width }) => `${url} ${width}w`).join(', '),
      src: fallback || widths[widths.length - 1]?.url,
      widths: widths.map((w) => w.width),
    }
  }
  return result
}

export const workImages = buildSet(workWebp, workJpg)
export const profileImages = buildSet(profileWebp, profileJpg)
